create table if not exists public.exercises (exercise_id text primary key, exercise_name text not null, body_region text not null, movement_pattern text not null, primary_muscle text not null, secondary_muscles text[] not null default '{}', equipment text[] not null default '{}', difficulty_level smallint not null check(difficulty_level between 1 and 4), exercise_role text not null, default_sets smallint not null, min_reps smallint not null, max_reps smallint not null, target_type text not null, default_rest_seconds integer not null, progression_type text not null, replacement_group text not null, beginner_friendly text not null, stability_demand text not null, lower_back_demand text not null, knee_demand text not null, shoulder_demand text not null, progression_friendliness text not null, is_unilateral boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.analytics_events(id bigint generated always as identity primary key,user_id uuid references public.profiles(id) on delete cascade,event_name text not null,properties jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.exercises enable row level security; alter table public.analytics_events enable row level security;
create policy "authenticated read exercises" on public.exercises for select to authenticated using(true);
create policy "admins manage exercises" on public.exercises for all to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','super_admin'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','super_admin')));
create policy "users insert own analytics" on public.analytics_events for insert to authenticated with check(auth.uid()=user_id);
create policy "admins read analytics" on public.analytics_events for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('admin','super_admin')));
create index if not exists exercises_pattern_idx on public.exercises(movement_pattern); create index if not exists exercises_active_idx on public.exercises(active); create index if not exists analytics_event_name_idx on public.analytics_events(event_name,created_at desc);
on conflict(exercise_id) do update set exercise_name=excluded.exercise_name,body_region=excluded.body_region,movement_pattern=excluded.movement_pattern,primary_muscle=excluded.primary_muscle,secondary_muscles=excluded.secondary_muscles,equipment=excluded.equipment,difficulty_level=excluded.difficulty_level,exercise_role=excluded.exercise_role,default_sets=excluded.default_sets,min_reps=excluded.min_reps,max_reps=excluded.max_reps,target_type=excluded.target_type,default_rest_seconds=excluded.default_rest_seconds,progression_type=excluded.progression_type,replacement_group=excluded.replacement_group,beginner_friendly=excluded.beginner_friendly,stability_demand=excluded.stability_demand,lower_back_demand=excluded.lower_back_demand,knee_demand=excluded.knee_demand,shoulder_demand=excluded.shoulder_demand,progression_friendliness=excluded.progression_friendliness,is_unilateral=excluded.is_unilateral,active=excluded.active,updated_at=now();
